def t(lang: str, key: str) -> str:
    entry = UI.get(key)
    if not entry:
        return key
    return entry.get(lang) or entry[DEFAULT_LANG]


def _lookup(table: dict, lang: str, key: str) -> str:
    entry = table.get(key)
    if not entry:
        return key
    return entry.get(lang) or entry[DEFAULT_LANG]


def residue_name(lang, key): return _lookup(RESIDUES, lang, key)
def condition_name(lang, key): return _lookup(CONDITIONS, lang, key)
def reuse_name(lang, key): return _lookup(REUSE, lang, key)
def caution_text(lang, key): return _lookup(CAUTIONS, lang, key)
def buyer_type_name(lang, key): return _lookup(BUYER_TYPES, lang, key)
